import math

def is_perfect_cube(n):
    if n == 0:
        return 0
    sign = 1 if n > 0 else -1
    abs_n = abs(n)

    # Estimate the cube root
    root_estimate = round(abs_n**(1/3))

    # Check the root and its neighbors due to floating point inaccuracies
    for k in range(max(0, root_estimate - 2), root_estimate + 3):
        if k**3 == abs_n:
            return sign * k
    return None

def check_case2(b):
    target = 8 * b**3 - 13
    return is_perfect_cube(target)

